-- Clients organ -- generated by noctusai_lib.domain.clients.sql

SET search_path = monica, public;

CREATE TABLE IF NOT EXISTS monica.clients (
    id                   UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id               UUID NOT NULL,
    name                 TEXT NOT NULL CHECK (length(btrim(name)) > 0),
    phone                TEXT,
    email                TEXT,
    doc                  TEXT,
    birth_date           DATE,
    status               TEXT NOT NULL,
    tags                 TEXT[] NOT NULL DEFAULT '{}',
    notes                TEXT,
    lead_id              UUID,
    whatsapp_chat_id     TEXT,
    default_price_cents  BIGINT CHECK (default_price_cents IS NULL OR default_price_cents >= 0),
    session_duration_min INTEGER CHECK (session_duration_min IS NULL OR session_duration_min > 0),
    started_at           DATE NOT NULL DEFAULT CURRENT_DATE,
    created_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by           UUID
);
-- One client per lead: the guard that makes the lead -> client conversion idempotent (NULL lead_id never conflicts).
CREATE UNIQUE INDEX IF NOT EXISTS uq_clients_lead ON monica.clients (org_id, lead_id);
CREATE INDEX IF NOT EXISTS idx_clients_name ON monica.clients (org_id, name, id);
ALTER TABLE monica.clients ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "clients_select_own_org" ON monica.clients;
DROP POLICY IF EXISTS "service_role_bypass" ON monica.clients;
CREATE POLICY "service_role_bypass" ON monica.clients FOR ALL TO service_role USING (true) WITH CHECK (true);
REVOKE ALL ON monica.clients FROM PUBLIC, anon, authenticated;
GRANT ALL ON monica.clients TO service_role;

CREATE TABLE IF NOT EXISTS monica.client_schedules (
    id                 UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id             UUID NOT NULL,
    client_id          UUID NOT NULL REFERENCES monica.clients(id) ON DELETE CASCADE,
    weekday            SMALLINT NOT NULL CHECK (weekday BETWEEN 0 AND 6),
    slot_time          TIME NOT NULL,
    duration_min       INTEGER NOT NULL CHECK (duration_min > 0),
    price_cents        BIGINT CHECK (price_cents IS NULL OR price_cents >= 0),
    starts_on          DATE NOT NULL,
    ends_on            DATE CHECK (ends_on IS NULL OR ends_on >= starts_on),
    active             BOOLEAN NOT NULL DEFAULT true,
    materialized_until DATE,
    created_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at         TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_client_schedules_client ON monica.client_schedules (org_id, client_id);
ALTER TABLE monica.client_schedules ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "client_schedules_select_own_org" ON monica.client_schedules;
CREATE POLICY "client_schedules_select_own_org" ON monica.client_schedules FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('monica')));
DROP POLICY IF EXISTS "service_role_bypass" ON monica.client_schedules;
CREATE POLICY "service_role_bypass" ON monica.client_schedules FOR ALL TO service_role USING (true) WITH CHECK (true);
GRANT SELECT ON monica.client_schedules TO authenticated;
GRANT ALL ON monica.client_schedules TO service_role;

CREATE TABLE IF NOT EXISTS monica.client_sessions (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id        UUID NOT NULL,
    client_id     UUID NOT NULL REFERENCES monica.clients(id) ON DELETE CASCADE,
    schedule_id   UUID REFERENCES monica.client_schedules(id) ON DELETE SET NULL,
    starts_at     TIMESTAMPTZ NOT NULL,
    duration_min  INTEGER NOT NULL CHECK (duration_min > 0),
    status        TEXT NOT NULL,
    price_cents   BIGINT CHECK (price_cents IS NULL OR price_cents >= 0),
    waive_charge  BOOLEAN NOT NULL DEFAULT false,
    notes         TEXT,
    entry_id      UUID,
    booking_rev   INTEGER NOT NULL DEFAULT 0,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);
-- One generated session per (schedule, instant): the guard that makes materialization idempotent.
CREATE UNIQUE INDEX IF NOT EXISTS uq_client_sessions_slot ON monica.client_sessions (schedule_id, starts_at);
CREATE INDEX IF NOT EXISTS idx_client_sessions_org_starts ON monica.client_sessions (org_id, starts_at, id);
CREATE INDEX IF NOT EXISTS idx_client_sessions_client_starts ON monica.client_sessions (org_id, client_id, starts_at);
ALTER TABLE monica.client_sessions ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "client_sessions_select_own_org" ON monica.client_sessions;
CREATE POLICY "client_sessions_select_own_org" ON monica.client_sessions FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('monica')));
DROP POLICY IF EXISTS "service_role_bypass" ON monica.client_sessions;
CREATE POLICY "service_role_bypass" ON monica.client_sessions FOR ALL TO service_role USING (true) WITH CHECK (true);
GRANT SELECT ON monica.client_sessions TO authenticated;
GRANT ALL ON monica.client_sessions TO service_role;

CREATE TABLE IF NOT EXISTS monica.client_payments (
    id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id         UUID NOT NULL,
    client_id      UUID NOT NULL REFERENCES monica.clients(id) ON DELETE RESTRICT,
    amount_cents   BIGINT NOT NULL CHECK (amount_cents > 0),
    paid_on        DATE NOT NULL,
    account_id     UUID NOT NULL,
    method         TEXT NOT NULL,
    notes          TEXT,
    settlement_ids UUID[] NOT NULL DEFAULT '{}',
    created_by     UUID,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_client_payments_client ON monica.client_payments (org_id, client_id, paid_on);
ALTER TABLE monica.client_payments ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "client_payments_select_own_org" ON monica.client_payments;
CREATE POLICY "client_payments_select_own_org" ON monica.client_payments FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('monica')));
DROP POLICY IF EXISTS "service_role_bypass" ON monica.client_payments;
CREATE POLICY "service_role_bypass" ON monica.client_payments FOR ALL TO service_role USING (true) WITH CHECK (true);
GRANT SELECT ON monica.client_payments TO authenticated;
GRANT ALL ON monica.client_payments TO service_role;
